import { assertSameOrigin, requireActor, requirePermission, revalidateActor } from '@/server/permissions';
import { apiError, json, readJsonObject } from '@/server/http';
import { exportSitePackage } from '@/server/site-package';
export const runtime = 'nodejs';
export async function POST(request: Request) { try { assertSameOrigin(request); let actor = await requireActor(request); requirePermission(actor, 'manage'); const input = await readJsonObject(request); /* 分发导出仍需有效管理员会话，不只检查请求开始时的角色。 */ actor = revalidateActor(actor, 'manage'); return json(await exportSitePackage(input)); } catch (e) { return apiError(e); } }
